using System.Security.Claims;using EmployeeAttendanceSystem.Data;using EmployeeAttendanceSystem.DTOs;using EmployeeAttendanceSystem.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace EmployeeAttendanceSystem.Controllers;
[ApiController][Authorize][Route("api/leaves")]
public class LeaveController:ControllerBase{readonly AppDbContext db;public LeaveController(AppDbContext db){this.db=db;}int U=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpPost]public IActionResult Create(LeaveDto d){if(d.EndDate.Date<d.StartDate.Date)return BadRequest(new{message="End date cannot be before start date"});var l=new LeaveRequest{UserId=U,StartDate=d.StartDate.Date,EndDate=d.EndDate.Date,Reason=d.Reason};db.LeaveRequests.Add(l);db.SaveChanges();return Ok(l);}[HttpGet]public IActionResult Mine()=>Ok(db.LeaveRequests.Where(x=>x.UserId==U).OrderByDescending(x=>x.CreatedAt).ToList());[HttpGet("summary")]public IActionResult Summary(){var approved=db.LeaveRequests.Where(x=>x.UserId==U&&x.Status=="Approved").ToList().Sum(x=>x.Days);const int allowance=2;return Ok(new{monthlyAllowance=allowance,approvedDays=approved,deductedDays=Math.Max(0,approved-allowance)});}[Authorize(Roles="HR")][HttpGet("all")]public IActionResult All()=>Ok(db.LeaveRequests.Include(x=>x.User).OrderByDescending(x=>x.CreatedAt).ToList());[Authorize(Roles="HR")][HttpPut("{id}/decision")]public IActionResult Decision(int id,LeaveDecisionDto d){var l=db.LeaveRequests.Find(id);if(l==null)return NotFound();if(d.Status!="Approved"&&d.Status!="Rejected")return BadRequest();l.Status=d.Status;db.SaveChanges();return Ok(l);}}
